        rankRoyal: "<strong>同花大順:</strong> A<span class=\"suit-red\">♥</span> K<span class=\"suit-red\">♥</span> Q<span class=\"suit-red\">♥</span> J<span class=\"suit-red\">♥</span> T<span class=\"suit-red\">♥</span>",
