    btnDesc: "<strong>BTN (Button):</strong> ポストフロップで最後に行動します。最も強いポジションで、広いレンジでブラインドをスチールできます。",
    sbBbDesc: "<strong>SB (Small Blind) & BB (Big Blind):</strong> 配られる前にブラインドを支払い、ポストフロップでは先に行動しやすいポジションです。",
    preflopStratTitle: "プリフロップ戦略",
    preflopStratDesc: "全員がフォールドして自分まで回ったとき、<strong>フォールド</strong> か <strong>Raise First In (RFI)</strong> を選びます。リン プ (BBにコールするだけ) は初心者には一般に悪い戦略です。主導権を取るためにレイズするか、フォールドしましょう。",
    advStratTitle: "上級戦略コンセプト",
    advUtgDesc: "<strong>UTG のタイトさ:</strong> Under the Gun は情報面で大きく不利です。後ろの全員からアクションを受けるため、非常にタイトなレンジが必要です。",
    adv3BetDesc: "<strong>3-Bet への対応:</strong> 「3-Bet」はプリフロップのリレイズです。UTG からオープンして3-betを受けた場合、相手はかなり強いレンジを持つことが多く、慎重にディフェンスするかプレミアムで4-Betします。",
    advImpliedDesc: "<strong>インプライドオッズ:</strong> セットなど強い役を作った後に期待できる追加利益です。相手のスタックが十分深い場合、小さいポケットペアで3-Betをコールできることがあります。",
    handRanksTitle: "基本ハンドランキング (強い順)",
    rankRoyal: "<strong>ロイヤルフラッシュ:</strong> A K Q J T (すべて同じスート)",
    rankStrFlush: "<strong>ストレートフラッシュ:</strong> 9 8 7 6 5 (連続、同じスート)",
    rankQuads: "<strong>フォーカード:</strong> Q Q Q Q 4",
    rankBoat: "<strong>フルハウス:</strong> K K K 2 2 (スリーカード + ペア)",
    rankFlush: "<strong>フラッシュ:</strong> 同じスートの5枚。",
    rankStraight: "<strong>ストレート:</strong> 5 6 7 8 9 (連続、スート混在)",
    rankTrips: "<strong>スリーカード:</strong> 7 7 7 A 2",
    rankTwoPair: "<strong>ツーペア:</strong> J J 9 9 4",
    rankPair: "<strong>ワンペア:</strong> A A 8 5 3",
    rankHigh: "<strong>ハイカード:</strong> A K 9 5 2 (最も高いカードが有効)",
    coachRfi: "<h3>Raise First In (Open)</h3><p>あなたが最初に自発的にポットへチップを入れるプレイヤーです。ポジションに応じて利益的なオープンレンジを構築します。</p><ul><li><strong>アーリーポジション (UTG):</strong> 非常にタイト。プレミアムペアと強いブロードウェイ中心。</li><li><strong>レイトポジション (BTN):</strong> 広め。投機的ハンドでもブラインドをスチールできます。</li></ul><p><strong>目安:</strong> ファーストインでは基本的にレイズ。オープンリンプはほぼ常にミスです。</p>",
    coachDefend: "<h3>レイズへの対応 (Defense)</h3><p>相手がすでにオープンし、強さを示しています。次の選択肢を考えます。</p><ul><li><strong>3-Bet:</strong> 最強ハンドと、良いブロッカーを持つ一部のブラフ。</li><li><strong>コール (Flat):</strong> ポジションがあり、フロップ後にプレイしやすいハンド。</li><li><strong>SB フォールド:</strong> SB はポストフロップで OOP。コールより3-Betかフォールド寄り。</li><li><strong>BB ディフェンス:</strong> BB は割引があるため、他ポジションより広く守れます。</li></ul>",
    coachPushFold: "<h3>ショートスタック: Push / Fold</h3><p>トーナメントでスタックが約15BB未満になると、戦略はプッシュかフォールドに単純化されます。</p><ul><li><strong>ポストフロップなし:</strong> 通常のレイズをするにはスタックが浅すぎます。</li><li><strong>選択肢:</strong> オールイン (Push) またはフォールド。</li><li><strong>数学重視:</strong> Nash チャートはフォールドエクイティとハンドエクイティからショーブ利益を決めます。</li><li><strong>スタック重要:</strong> スタックが浅いほどレンジは広がります。</li></ul>",
    coachCustom: "<h3>カスタム練習モード</h3><p>レンジエディターで作った自分のレンジに対して練習します。</p><ul><li><strong>自由選択:</strong> 保存済みレンジを選択できます。</li><li><strong>無限ドリル:</strong> 表記に基づいてランダムハンドを出題します。</li><li><strong>制限なし:</strong> 特定のサブレンジや境界ハンドも検証できます。</li></ul>",
    scenarioRfi: (hand, pos) => `${hand} が配られました。${pos} でファーストインです。`,
    scenarioPush: (hand, pos, stack) => `${hand} が配られました。${pos} でスタックは ${stack || 10}bb です。`,
    scenarioDefend: (hand) => `${hand} が配られました。CO が 2.5bb にレイズし、あなたは BTN です。`,
    scenarioDefendFull: (hand, villain, hero) => `${hand} が配られました。${villain} が 2.5bb にレイズ。あなたは ${hero} です。`,
    scenarioFacing3BetDrill: "{combo} が配られました。{hero} が {openSize}bb にオープンし、{villain} が {threeBetSize}bb へ 3-Bet。実効スタック: {stack}bb。",
    scenarioRfiDrill: "{combo} が配られました。{hero} からファーストインです。{note}",
    scenarioDefenseDrill: "{combo} が配られました。{opener} が {openSize}bb にオープン。あなたは {hero} です。",
    scenarioPushFoldDrill: "{combo} が配られました。{hero} で {stack}bb 持ちです。{ante}",
    evalRfiUtgRaise: (combo) => `UTG で ${combo} はプレイ可能な強さです。UTG は非常にタイトなレンジが必要です。主導権を取るためにレイズします。`,
    evalRfiRaise: (pos, combo) => `${pos} で ${combo} はオープンレンジに入ります。2.5bb〜3bb にレイズします。`,
    evalRfiUtgFold: (combo) => `UTG で ${combo} はフォールドです。ポストフロップの不利を避けるため、UTG では規律が必要です。`,
    evalRfiFold: (pos, combo) => `${pos} で ${combo} は通常オープンハンドとしてはフォールドです。`,
    evalPush: (pos, combo, stack) => `${pos} で ${stack || 10}bb の ${combo} はオールインショーブが利益的です。フォールドエクイティとハンドエクイティで +EV になります。`,
    evalPushFold: (pos, combo, stack) => `${pos} で ${stack || 10}bb の ${combo} は利益的にショーブするにはエクイティ不足です。フォールドして良いスポットを待ちます。`,
    evalDefendRaise: (combo, villain, hero) => `${villain} のレイズに対して、${hero} の ${combo} はバリューで 3-Bet できる強さです。`,
    evalDefendCall: (combo, villain, hero) => `${villain} のレイズに対して、${hero} の ${combo} はフロップを見るコールに値します。十分なエクイティとプレイアビリティがあります。`,
    evalDefendFold: (combo, villain, hero) => `${villain} のレイズに対して、${hero} の ${combo} は続行するには弱すぎます。フォールドします。`,
