    boardTextureMissedDrawRelevant: "錯過聽牌相關",
    boardTextureStatic: "靜態牌面",
    boardTexturePolarized: "兩極化",
    allStreetScenarioTitle_starter_flop_cbet_a72r: "翻牌持續下注：A 高乾燥牌面",
    allStreetScenarioTitle_starter_flop_checkraise_884tt: "翻牌過牌加注：低張成對牌面",
    allStreetScenarioTitle_starter_turn_barrel_ksqs5d2c: "轉牌連續開火：高張密集雙花牌面",
    allStreetScenarioTitle_starter_turn_probe_9h6h2c8h: "轉牌探測下注：完成聽牌的轉牌",
    allStreetScenarioTitle_starter_river_bluffcatch_jt722: "河牌抓詐唬：成對且聽牌未完成",
    allStreetScenarioTitle_starter_river_value_akq62: "河牌價值下注：高張 runout 的薄價值",
    allStreetScenarioTitle_starter_river_facing_overbet_ak6jt: "面對超池下注：河牌兩極化壓力",
    allStreetScenarioExplanation_starter_flop_cbet_a72r: "A 高乾燥牌面通常讓翻前加注者有範圍優勢，也更常握有最強牌優勢。強 Ax、頂 Set 和有阻斷牌效果的空氣牌適合小注；勝率實現較差的牌可以過牌。",
    allStreetScenarioExplanation_starter_flop_checkraise_884tt: "成對牌面可能讓大盲有更多明三條與保護性加注。用明三條、葫蘆和部分後門聽牌或阻斷牌詐唬過牌加注；中等攤牌價值多用跟注。",
    allStreetScenarioExplanation_starter_turn_barrel_ksqs5d2c: "這張轉牌讓強高張價值牌和高勝率阻斷牌詐唬繼續留在下注範圍。用能壓迫一對抓詐唬的牌繼續下注，弱攤牌價值或低勝率空氣牌過牌。",
    allStreetScenarioExplanation_starter_turn_probe_9h6h2c8h: "翻前進攻者翻牌過牌後，轉牌完成聽牌時，防守方可透過探測下注取得 EV。用完成的聽牌與能阻止對手勝率實現的牌小注；沒有槓桿的空氣牌過牌。",
    allStreetScenarioExplanation_starter_river_bluffcatch_jt722: "聽牌未完成且河牌成對時，適合保留阻斷價值牌或不阻斷詐唬的抓詐唬牌。用有用阻斷牌的頂對跟注；阻斷牌屬性差的牌棄牌。",
    allStreetScenarioExplanation_starter_river_value_akq62: "河牌價值下注不只限於最強牌。當較差的抓詐唬牌仍會跟注且被加注壓力較低時，薄價值可使用較小尺度。",
    allStreetScenarioExplanation_starter_river_facing_overbet_ak6jt: "面對兩極化超池下注，先看底池賠率，再保留阻斷價值牌或不阻斷錯過聽牌的手牌。沒有好阻斷牌的中強牌應過度棄牌。"
