function simplifyChineseText(value) {
    return String(value ?? '').replace(/[\u3400-\u9fff]/g, char => SIMPLIFIED_CHINESE_CHAR_MAP[char] || char);
}

function createSimplifiedChinesePack(source) {
    const cloneValue = value => {
        if (typeof value === 'string') return simplifyChineseText(value);
        if (typeof value === 'function') {
            return (...args) => {
                const result = value(...args);
                return typeof result === 'string' ? simplifyChineseText(result) : result;
            };
        }
        if (Array.isArray(value)) return value.map(cloneValue);
        if (value && typeof value === 'object') {
            return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, cloneValue(item)]));
        }
        return value;
    };
    return cloneValue(source);
}

